mapper.select:
SELECT /* getYearComparison */
       #{currentYear} AS CURRENT_YEAR
     , #{previousYear} AS PREVIOUS_YEAR
     , COALESCE((
           SELECT SUM(D.READ_SECS)
             FROM TB_RDATDX D
            WHERE D.USER_NUMB = #{userNumb}
              AND D.READ_DATE >= #{currentStart}
              AND D.READ_DATE < #{currentEnd}
       ), 0) AS CURRENT_READ_SECS
     , COALESCE((
           SELECT SUM(D.READ_SECS)
             FROM TB_RDATDX D
            WHERE D.USER_NUMB = #{userNumb}
              AND D.READ_DATE >= #{previousStart}
              AND D.READ_DATE < #{previousEnd}
       ), 0) AS PREVIOUS_READ_SECS
     , COALESCE((
           SELECT COUNT(*)
             FROM TB_RDATDX D
            WHERE D.USER_NUMB = #{userNumb}
              AND D.READ_DATE >= #{currentStart}
              AND D.READ_DATE < #{currentEnd}
              AND D.READ_SECS > 0
       ), 0) AS CURRENT_READ_DAYS
     , COALESCE((
           SELECT COUNT(*)
             FROM TB_RDATDX D
            WHERE D.USER_NUMB = #{userNumb}
              AND D.READ_DATE >= #{previousStart}
              AND D.READ_DATE < #{previousEnd}
              AND D.READ_SECS > 0
       ), 0) AS PREVIOUS_READ_DAYS
     , COALESCE((
           SELECT COUNT(*)
             FROM TM_REPORT R
            WHERE R.USER_NUMB = #{userNumb}
              AND R.REPT_STAT = #{doneStat}
              AND R.REPT_ENDT >= DATE_FORMAT(#{currentStart}, '%Y-%m-%d')
              AND R.REPT_ENDT < DATE_FORMAT(#{currentEnd}, '%Y-%m-%d')
       ), 0) AS CURRENT_DONE_BOOKS
     , COALESCE((
           SELECT COUNT(*)
             FROM TM_REPORT R
            WHERE R.USER_NUMB = #{userNumb}
              AND R.REPT_STAT = #{doneStat}
              AND R.REPT_ENDT >= DATE_FORMAT(#{previousStart}, '%Y-%m-%d')
              AND R.REPT_ENDT < DATE_FORMAT(#{previousEnd}, '%Y-%m-%d')
       ), 0) AS PREVIOUS_DONE_BOOKS

