/* uptReadingStatsSetting */
INSERT INTO TM_USSETX (
            USER_NUMB
          , RSTA_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{publicYsno}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)
ON DUPLICATE KEY UPDATE
       RSTA_YSNO = VALUES(RSTA_YSNO)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
